examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchText(
        text = {{title}},
        style = MonarchTextStyle.Title,
        modifier = Modifier.semantics { heading() },
    )
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space6)) {
        MonarchTableOfContents(
            items = listOf(
                MonarchTableOfContentsItem({{sections.0.title}}, "general"),
                MonarchTableOfContentsItem({{sections.1.title}}, "notifications"),
                MonarchTableOfContentsItem("Danger zone", "danger"),
            ),
            selectedId = "general",
            onSelect = {},
            modifier = Modifier.width(200.dp),
            showTitle = false,
        )
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
            MonarchSectionCard(title = {{sections.0.title}}) {
                MonarchTextField(
                    value = workspaceName,
                    onValueChange = { workspaceName = it },
                    label = {{sections.0.row.label}},
                )
            }
            MonarchSectionCard(title = {{sections.1.title}}) {
                MonarchSwitchRow(
                    checked = digest,
                    onCheckedChange = { digest = it },
                    label = {{sections.1.row.label}},
                    description = {{sections.1.row.description}},
                )
            }
            MonarchSectionCard(title = "Danger zone", tone = MonarchTone.Danger) {
                Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                    MonarchText(text = {{danger.title}}, style = MonarchTextStyle.BodyStrong)
                    MonarchText(text = {{danger.description}}, style = MonarchTextStyle.Caption)
                    MonarchButton(text = {{danger.action}}, onClick = {}, variant = MonarchButtonVariant.Danger)
                }
            }
        }
    }
}

examples.code:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchText(
        text = "Workspace settings",
        style = MonarchTextStyle.Title,
        modifier = Modifier.semantics { heading() },
    )
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space6)) {
        MonarchTableOfContents(
            items = listOf(
                MonarchTableOfContentsItem("General", "general"),
                MonarchTableOfContentsItem("Notifications", "notifications"),
                MonarchTableOfContentsItem("Danger zone", "danger"),
            ),
            selectedId = "general",
            onSelect = {},
            modifier = Modifier.width(200.dp),
            showTitle = false,
        )
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
            MonarchSectionCard(title = "General") {
                MonarchTextField(
                    value = workspaceName,
                    onValueChange = { workspaceName = it },
                    label = "Workspace name",
                )
            }
            MonarchSectionCard(title = "Notifications") {
                MonarchSwitchRow(
                    checked = digest,
                    onCheckedChange = { digest = it },
                    label = "Email digest",
                    description = "A summary once a week.",
                )
            }
            MonarchSectionCard(title = "Danger zone", tone = MonarchTone.Danger) {
                Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                    MonarchText(text = "Delete this workspace", style = MonarchTextStyle.BodyStrong)
                    MonarchText(text = "Removes the workspace and everything in it.", style = MonarchTextStyle.Caption)
                    MonarchButton(text = "Delete workspace", onClick = {}, variant = MonarchButtonVariant.Danger)
                }
            }
        }
    }
}
